<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\Admin\StoreUserRequest; use App\Http\Requests\Admin\UpdateUserRequest; use App\Models\User; use App\Repositories\UserRepository; use App\Services\UserService; use Illuminate\Http\Request; use Inertia\Inertia; use Spatie\Permission\Models\Role;
class UserController extends Controller { public function __construct(private UserRepository $repo,private UserService $service){} public function index(Request $request){return Inertia::render('Admin/Users/Index',['users'=>$this->repo->paginate($request->only('search')),'filters'=>$request->only('search')]);} public function create(){return Inertia::render('Admin/Users/Create',['roles'=>Role::orderBy('name')->pluck('name')]);} public function store(StoreUserRequest $request){$this->service->create($request->validated());return redirect()->route('admin.users.index')->with('success','User created successfully.');} public function edit(User $user){$user->load('roles');return Inertia::render('Admin/Users/Edit',['user'=>$user,'roles'=>Role::orderBy('name')->pluck('name')]);} public function update(UpdateUserRequest $request,User $user){abort_if($user->hasRole('Super Admin')&&!auth()->user()->hasRole('Super Admin'),403);$this->service->update($user,$request->validated());return redirect()->route('admin.users.index')->with('success','User updated successfully.');} public function destroy(User $user){abort_if($user->is(auth()->user()),422,'You cannot delete your own account.');abort_if($user->hasRole('Super Admin'),403,'Super Admin cannot be deleted.');$this->service->delete($user);return back()->with('success','User deleted successfully.');} }
